from fractions import Fraction
import math


def solve(task):
    a, b, c = 1, -5, 6
    d = b * b - 4 * a * c
    if d < 0:
        return {"exact": "нет решений"}
    r = math.isqrt(d)
    if r * r != d:
        raise ValueError("irrational roots are not expected here")
    roots = sorted({Fraction(-b - r, 2 * a), Fraction(-b + r, 2 * a)})
    return {"exact": "; ".join(str(x) for x in roots)}

from fractions import Fraction


def solve(task):
    a, b, c = 1, -5, 6
    roots = set()
    for q in range(1, 13):
        for p in range(-240, 241):
            x = Fraction(p, q)
            if a * x * x + b * x + c == 0:
                roots.add(x)
    if not roots:
        return {"exact": "нет решений"}
    return {"exact": "; ".join(str(x) for x in sorted(roots))}

